// Let's write a function to collect products on the current page
async function getPageProducts() {
  return await browserjs(tabId, () => {
    // Find all product links
    const tiles = Array.from(document.querySelectorAll('.rc-producttile, li, div'))
      .map(el => {
        const titleEl = el.querySelector('h3, .rf-refurb-productcard-title, a[data-autom="productTitle"]');
        const linkEl = el.querySelector('a[href*="/shop/product/"]');
        const priceEl = el.querySelector('.rf-refurb-price-current, .as-price-currentprice, .now-price');
        if (titleEl && linkEl) {
          return {
            title: titleEl.innerText.trim(),
            link: linkEl.href,
            price: priceEl ? priceEl.innerText.trim() : el.innerText.match(/\$[\d,]+(\.\d{2})?/)?.[0] || null,
            fullText: el.innerText.trim().replace(/\s+/g, ' ')
          };
        }
        return null;
      })
      .filter(Boolean);

    // Deduplicate by link
    const unique = [];
    const seen = new Set();
    for (const t of tiles) {
      if (!seen.has(t.link)) {
        seen.add(t.link);
        unique.push(t);
      }
    }
    return unique;
  });
}

// Let's go to page 1 first
await browserjs(tabId, () => {
  const input = document.querySelector('[data-analytics-pagination="pageinput"]');
  if (input) {
